<script setup lang="ts">
import { ref, watch } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsSuccess, SplitIdStringsFromText } from "@/util/tips";
import {
  GetPermissionGroupMemberList,
  PostPermissionGroupMemberSave,
} from "@/apis/permission";
import { PostUserParse } from "@/apis/user";
import type { GroupMember } from "@/types/permission";

/**
 * 用户组成员管理（抽屉内容）。
 *
 * 它原先是与「用户组」「角色」并列的一个 tab，需要管理员在另一个页面里**再选一次组**。
 * 那个模型是错的：成员是组的一部分，看某个组时顺手管它的成员才是自然路径；平铺成并列
 * tab 还多出一次「先选组」的动作，而且两个 tab 之间的选择状态会各自独立、互相不知道。
 *
 * 现在由「用户组」列表点进来，组 id 由父组件给出。
 */
const props = defineProps<{
  /** 正在管理成员的组 id */
  groupId: number;
  /** 组名，仅用于标题展示 */
  groupName: string;
}>();

const emit = defineEmits<{
  /** 成员发生变化：父组件据此刷新成员数 */
  (event: "changed"): void;
}>();

const { globalProperties } = useCurrentInstance();

const keyword = ref("");
const loading = ref(false);
const members = ref([] as GroupMember[]);
const total = ref(0);
const page = ref(1);
const pageSize = ref(20);

const loadMembers = async () => {
  loading.value = true;
  try {
    const res = await GetPermissionGroupMemberList(
      props.groupId,
      keyword.value.trim(),
      page.value,
      pageSize.value
    );
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    members.value = res.data?.list ?? [];
    total.value = res.data?.total ?? 0;
  } finally {
    loading.value = false;
  }
};

// 抽屉每次换组都要重置分页与关键词：沿用上一次的状态会让「第 3 页」这种值落到一个
// 成员数完全不同的组上，看起来像是数据错乱
watch(
  () => props.groupId,
  () => {
    page.value = 1;
    keyword.value = "";
    loadMembers();
  },
  { immediate: true }
);

watch(page, loadMembers);
watch(pageSize, () => {
  page.value = 1;
  loadMembers();
});

const handleSearch = () => {
  page.value = 1;
  loadMembers();
};

// ===== 添加成员 =====

const addVisible = ref(false);
const addInput = ref("");
const adding = ref(false);
/** 上一次解析中未能找到的用户名，用于明确告诉管理员「哪些没加进去」 */
const missingNames = ref([] as string[]);

const openAdd = () => {
  addInput.value = "";
  missingNames.value = [];
  addVisible.value = true;
};

const handleAdd = async () => {
  // 复用项目的分隔约定（空白 + 英文逗号），额外把中文逗号也视为分隔符——
  // 管理员常常是从中文文档里粘一份名单过来。
  // 该工具函数名字里带 Id，但实现（strings.Fields 语义 + 逗号拆分 + 去空）与本场景
  // 完全一致，因此复用而不是再写一份。
  const names = SplitIdStringsFromText(addInput.value.replace(/，/g, ","));
  if (names.length === 0) {
    ShowErrorTips(globalProperties, "请输入要添加的用户名");
    return;
  }
  adding.value = true;
  try {
    const parsed = await PostUserParse(names);
    if (parsed.code !== 0) {
      ShowErrorTips(globalProperties, parsed.code);
      return;
    }
    // PostUserParse 走的是未类型化的既有接口（apis/user.ts 未标注返回类型），
    // 这里就地收窄成组成员形状，避免下游出现隐式 any
    const users = (parsed.data?.users ?? []) as GroupMember[];
    if (users.length === 0) {
      missingNames.value = names;
      ShowErrorTips(globalProperties, "这些用户名都没有找到对应的用户");
      return;
    }
    // 后端只返回找得到的用户，因此差集就是没找到的
    const foundNames = new Set(users.map((user) => user.username));
    missingNames.value = names.filter((name) => !foundNames.has(name));

    const res = await PostPermissionGroupMemberSave({
      group_id: props.groupId,
      add_user_ids: users.map((user) => user.id),
      remove_user_ids: [],
    });
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(
      globalProperties,
      missingNames.value.length > 0
        ? `已添加 ${users.length} 人，另有 ${missingNames.value.length} 个用户名未找到`
        : `已添加 ${users.length} 人`
    );
    if (missingNames.value.length === 0) {
      addVisible.value = false;
    }
    emit("changed");
    await loadMembers();
  } finally {
    adding.value = false;
  }
};

const handleRemove = async (row: GroupMember) => {
  const res = await PostPermissionGroupMemberSave({
    group_id: props.groupId,
    add_user_ids: [],
    remove_user_ids: [row.id],
  });
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  ShowTextTipsSuccess(globalProperties, "已移出该组");
  emit("changed");
  await loadMembers();
};
</script>

<template>
  <div class="member-drawer">
    <div class="panel-toolbar">
      <t-input
        v-model="keyword"
        placeholder="按用户名或昵称搜索"
        style="width: 220px"
        clearable
        @enter="handleSearch"
        @clear="handleSearch"
      />
      <t-button variant="outline" @click="handleSearch">搜索</t-button>
      <t-button theme="primary" @click="openAdd">添加成员</t-button>
      <span class="panel-hint">
        成员在组内共同继承该组绑定的角色。移出后他会失去这些角色带来的权限，
        但如果同一角色还被直接授予他，权限不会消失。
      </span>
    </div>

    <t-table
      row-key="id"
      :data="members"
      :loading="loading"
      :scroll="{ x: 560 }"
      :columns="[
        { title: '用户名', colKey: 'username', width: 200 },
        { title: '昵称', colKey: 'nickname', width: 220 },
        { title: '操作', colKey: 'op', width: 100, fixed: 'right' },
      ]"
    >
      <template #op="{ row }">
        <t-popconfirm content="移出该组后，他将失去这个组带来的角色与权限。" @confirm="handleRemove(row)">
          <t-link theme="danger">移出</t-link>
        </t-popconfirm>
      </template>
    </t-table>

    <div class="panel-pagination">
      <t-pagination
        v-model="page"
        v-model:page-size="pageSize"
        :total="total"
        :page-size-options="[10, 20, 50, 100]"
        show-jumper
      />
    </div>

    <t-dialog
      v-model:visible="addVisible"
      header="添加成员"
      :confirm-btn="{ loading: adding }"
      width="520px"
      @confirm="handleAdd"
    >
      <t-form label-align="top">
        <t-form-item label="用户名">
          <t-textarea
            v-model="addInput"
            :autosize="{ minRows: 3 }"
            placeholder="多个用户名用空格或逗号分隔"
          />
          <template #help>按用户名精确匹配；未找到的名字会被单独列出来，不会静默忽略。</template>
        </t-form-item>
      </t-form>

      <t-alert
        v-if="missingNames.length > 0"
        theme="warning"
        :message="`以下用户名未找到：${missingNames.join('、')}`"
      />
    </t-dialog>
  </div>
</template>

