.member-drawer .panel-toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.member-drawer .panel-hint {
  flex-basis: 100%;
  color: var(--td-text-color-secondary);
  font-size: 13px;
  line-height: 1.6;
}

.member-drawer .panel-pagination {
  display: flex;
  justify-content: flex-end;
  margin-top: 12px;
}
</style>
