// 权限管理后台的接口封装。
//
// 路径与方法名一一对应后端的 PermissionController（见 web/controller/permission.go），
// 那侧有一份 TestPermissionRoutes 钉住这些路径，改名会立刻失败——
// 这里不再重复维护一份路径清单，只保证调用处与之一致。
import httpRequest from "@/apis/axios-api";

import type { CodeResult } from "@/types/request";
import type {
  GroupMemberPage,
  GroupMemberSaveRequest,
  GroupSaveRequest,
  PermissionAuditPage,
  PermissionCatalog,
  RoleInfo,
  RoleRefs,
  RoleSaveRequest,
  UserAccountBrief,
  UserAuthInfo,
  UserGroupInfo,
  UserGroupSaveRequest,
  UserRoleSaveRequest,
} from "@/types/permission";

/** 权限点清单（按分组，供勾选树渲染） */
export function GetPermissionCatalog(): Promise<CodeResult<PermissionCatalog>> {
  return httpRequest<unknown, CodeResult<PermissionCatalog>>({
    url: "/system/permission/catalog",
    method: "get",
  });
}

// ===== 角色 =====

export function GetPermissionRoleList(): Promise<CodeResult<RoleInfo[]>> {
  return httpRequest<unknown, CodeResult<RoleInfo[]>>({
    url: "/system/permission/role/list",
    method: "get",
  });
}

/** 某个角色被谁引用：直接持有的用户 + 绑定了它的用户组（补上列表里只有计数的缺口） */
export function GetPermissionRoleRefs(id: number): Promise<CodeResult<RoleRefs>> {
  return httpRequest<unknown, CodeResult<RoleRefs>>({
    url: "/system/permission/role/refs",
    method: "get",
    params: { id },
  });
}

export function PostPermissionRoleSave(request: RoleSaveRequest): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/system/permission/role/save",
    method: "post",
    data: request,
  });
}

export function PostPermissionRoleDelete(id: number): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/system/permission/role/delete",
    method: "post",
    params: { id },
  });
}

