// ===== 组成员 =====

export function GetPermissionGroupMemberList(
  groupId: number,
  keyword: string,
  page: number,
  pageSize: number
): Promise<CodeResult<GroupMemberPage>> {
  return httpRequest<unknown, CodeResult<GroupMemberPage>>({
    url: "/system/permission/group/member/list",
    method: "get",
    params: {
      group_id: groupId,
      keyword,
      page,
      page_size: pageSize,
    },
  });
}

/**
 * 增量增删组成员。
 *
 * 刻意不做「提交完整名单」：组成员可能成百上千，而前端只能拿到当前页；
 * 全量提交会把「没显示在页面上的人」当成「应该被移除」。
 */
export function PostPermissionGroupMemberSave(
  request: GroupMemberSaveRequest
): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/system/permission/group/member/save",
    method: "post",
    data: request,
  });
}

// ===== 用户授权 =====

export function GetPermissionUserAuth(userId: number): Promise<CodeResult<UserAuthInfo>> {
  return httpRequest<unknown, CodeResult<UserAuthInfo>>({
    url: "/system/permission/user/auth",
    method: "get",
    params: { user_id: userId },
  });
}

/**
 * 按用户名或昵称模糊搜索用户，供「用户授权」页的选人输入框补全。
 *
 * 关键词少于 2 个字符时后端直接返回空列表（不查库）：单字符会命中几乎所有用户，
 * 前端也据此不发请求，避免每一次按键都打一次接口。
 */
export function GetPermissionUserSearch(
  keyword: string
): Promise<CodeResult<UserAccountBrief[]>> {
  return httpRequest<unknown, CodeResult<UserAccountBrief[]>>({
    url: "/system/permission/user/search",
    method: "get",
    params: { keyword },
  });
}

