// 权限管理后台的类型定义。
//
// 字段名与后端 foundation-view/permission.go 的 JSON tag 一一对应（snake_case），
// 不做驼峰转换——转换层越厚，后端改一个字段名时越难发现前端漏改。

/** 权限点（后台勾选树的一项） */
export interface PermissionItem {
  key: string;
  name: string;
  description: string;
}

/** 按域分组的权限点（分组顺序与名称由后端注册表给出，前端只渲染不重排） */
export interface PermissionGroup {
  group: string;
  name: string;
  items: PermissionItem[];
}

export interface PermissionCatalog {
  groups: PermissionGroup[];
}

export interface RoleInfo {
  id: number;
  key: string;
  name: string;
  description: string;
  /** 超管：自动拥有全部权限点，permissions 会是空数组而不是全部（界面应显示「自动拥有全部」） */
  is_super: boolean;
  /** 内置：不可删除；改它需要超管身份 */
  is_builtin: boolean;
  sort: number;
  permissions: string[];
  /** 直接拥有该角色的用户数 */
  user_refs: number;
  /** 绑定该角色的用户组数 */
  group_refs: number;
}

/** 绑定了某角色的用户组 */
export interface RoleRefGroup {
  id: number;
  key: string;
  name: string;
  /** 组内成员数：让「删掉这个角色会通过这个组影响多少人」一眼可见 */
  member_count: number;
}

/**
 * 用于「挑人」的用户简要信息。
 *
 * 刻意只有 id / 用户名 / 昵称，与后端的 UserAccountInfo 一致：这是补全列表里的一项，
 * 不该带上邮箱、手机号之类与「挑人」无关、但泄露面更大的字段。
 */
export interface UserAccountBrief {
  id: number;
  username: string;
  nickname?: string;
}

/**
 * 某个角色被谁引用。
 *
 * `users` 与 `groups` 分开而不是合成一个名单：它们的处置动作完全不同——撤掉某个人的
 * 直接授权，与解绑用户组的角色，影响的是不同的人群。这与「用户授权」页把直接角色与
 * 组继承分开显示是同一个理由。
 */
export interface RoleRefs {
  role_key: string;
  role_name: string;
  users: UserAccountBrief[];
  /** 直接持有者的实际总数；大于 users.length 时说明列表被截断 */
  user_total: number;
  groups: RoleRefGroup[];
}

export interface UserGroupInfo {
  id: number;
  key: string;
  name: string;
  description: string;
  is_builtin: boolean;
  sort: number;
  /** 绑定的角色 Key */
  roles: string[];
  member_count: number;
}

/** 某用户的授权全貌。同时给出「直接的」与「有效的」两组数据，便于区分来源 */
export interface UserAuthInfo {
  user_id: number;
  username: string;
  nickname: string;
  /** 直接授予的角色 Key */
  direct_roles: string[];
  /** 所属用户组 id */
  group_ids: number[];
  /** 有效角色 Key（直接 ∪ 组继承） */
  roles: string[];
  /** 有效权限点 */
  permissions: string[];
  is_super: boolean;
}

export interface PermissionAuditItem {
  id: number;
  operator_id: number;
  operator_name: string;
  action: string;
  target_type: string;
  target_id: string;
  /** JSON 文本，按 action 渲染差异 */
  detail: string;
  insert_time: string;
}

export interface PermissionAuditPage {
  items: PermissionAuditItem[];
  has_more: boolean;
}

/** 组成员（后端复用 UserAccountInfo 的形状） */
export interface GroupMember {
  id: number;
  username: string;
  nickname: string;
}

export interface GroupMemberPage {
  list: GroupMember[];
  total: number;
  page: number;
  page_size: number;
}

// ===== 请求体 =====

export interface RoleSaveRequest {
  /** 0 表示新建；非 0 为更新（此时 key 被后端忽略，它是被引用的稳定标识） */
  id: number;
  key: string;
  name: string;
  description: string;
  sort: number;
  permissions: string[];
}

export interface GroupSaveRequest {
  id: number;
  key: string;
  name: string;
  description: string;
  sort: number;
  roles: string[];
}

export interface GroupMemberSaveRequest {
  group_id: number;
  add_user_ids: number[];
  remove_user_ids: number[];
}

export interface UserRoleSaveRequest {
  user_id: number;
  roles: string[];
}

export interface UserGroupSaveRequest {
  user_id: number;
  group_ids: number[];
}

/** 审计动作的中文说明与标签主题（后端返回的是 role.create 这类稳定标识） */
export function GetAuditActionText(action: string): string {
  switch (action) {
    case "role.create":
      return "新建角色";
    case "role.update":
      return "修改角色";
    case "role.delete":
      return "删除角色";
    case "group.create":
      return "新建用户组";
    case "group.update":
      return "修改用户组";
    case "group.delete":
      return "删除用户组";
    case "group.member.change":
      return "变更组成员";
    case "user.role.change":
      return "变更用户角色";
    case "user.group.change":
      return "变更用户所属组";
    default:
      return action;
  }
}
