<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsSuccess } from "@/util/tips";
import {
  GetPermissionCatalog,
  GetPermissionRoleList,
  GetPermissionRoleRefs,
  PostPermissionRoleDelete,
  PostPermissionRoleSave,
} from "@/apis/permission";
import type {
  PermissionGroup,
  RoleInfo,
  RoleRefs,
  RoleSaveRequest,
} from "@/types/permission";

const { globalProperties } = useCurrentInstance();

const loading = ref(false);
const roles = ref([] as RoleInfo[]);
const catalog = ref([] as PermissionGroup[]);

// 权限点 key → 名称，用于在表格里把 key 展示成人能读的标签
const permissionNames = computed(() => {
  const map: Record<string, string> = {};
  for (const group of catalog.value) {
    for (const item of group.items) {
      map[item.key] = item.name;
    }
  }
  return map;
});

const loadRoles = async () => {
  loading.value = true;
  try {
    const res = await GetPermissionRoleList();
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    roles.value = res.data ?? [];
  } finally {
    loading.value = false;
  }
};

const loadCatalog = async () => {
  const res = await GetPermissionCatalog();
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  catalog.value = res.data?.groups ?? [];
};

onMounted(async () => {
  // 两个请求互不依赖，但都要在渲染勾选树前就位
  await Promise.all([loadCatalog(), loadRoles()]);
});

// ===== 编辑 =====

const editVisible = ref(false);
const saving = ref(false);
const editForm = ref({} as RoleSaveRequest);

const editTitle = computed(() => (editForm.value.id > 0 ? "编辑角色" : "新建角色"));
/** 编辑中的角色是否超管：超管不展示权限点勾选（判定短路，勾了也不起作用） */
const editingSuper = computed(() => {
  const role = roles.value.find((item) => item.id === editForm.value.id);
  return role?.is_super === true;
});
/** 编辑中的角色是否内置：内置角色的标识不可改（它是被引用的稳定标识） */
const editingBuiltin = computed(() => {
  const role = roles.value.find((item) => item.id === editForm.value.id);
  return role?.is_builtin === true;
});

const openCreate = () => {
  editForm.value = {
    id: 0,
    key: "",
    name: "",
    description: "",
    sort: 0,
    permissions: [],
  };
  editVisible.value = true;
};

const openEdit = (row: RoleInfo) => {
  editForm.value = {
    id: row.id,
    key: row.key,
    name: row.name,
    description: row.description,
    sort: row.sort,
    permissions: [...row.permissions],
  };
  editVisible.value = true;
};

const handleSave = async () => {
  if (!editForm.value.name.trim()) {
    ShowErrorTips(globalProperties, "请填写角色名称");
    return;
  }
  if (editForm.value.id <= 0 && !editForm.value.key.trim()) {
    ShowErrorTips(globalProperties, "请填写角色标识");
    return;
  }
  saving.value = true;
  try {
    const res = await PostPermissionRoleSave(editForm.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "已保存");
    editVisible.value = false;
    await loadRoles();
  } finally {
    saving.value = false;
  }
};

const handleDelete = async (row: RoleInfo) => {
  const res = await PostPermissionRoleDelete(row.id);
  if (res.code !== 0) {
    // 最可能的两种失败是「仍被引用」（100106）与「内置/超管受保护」（100107），
    // 后端的错误码文案已经说明了该怎么办，这里直接透出即可
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  ShowTextTipsSuccess(globalProperties, "已删除");
  await loadRoles();
};

// ===== 引用详情 =====

const refsVisible = ref(false);
const refsLoading = ref(false);
const refs = ref(null as RoleRefs | null);

/**
 * 打开「谁在用这个角色」。
 *
 * 列表里只有「N 用户 / M 组」的计数，管理员看得到数字却查不到是谁——想知道「谁能管题目」
 * 就得切到「用户授权」逐个试。这一步把那个断点接上。
 *
 * 两个列表都为空时不自动关闭弹窗：明确显示「没有任何人持有」本身就是有效信息
 * （它意味着这个角色可以安全删除），比弹窗一闪而过更好。
 */
const openRefs = async (row: RoleInfo) => {
  refsVisible.value = true;
  refsLoading.value = true;
  refs.value = null;
  try {
    const res = await GetPermissionRoleRefs(row.id);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      refsVisible.value = false;
      return;
    }
    refs.value = res.data;
  } finally {
    refsLoading.value = false;
  }
};

/** 表格里的权限点展示：超管显示「自动拥有全部」，其余显示前若干个标签 */
const rolePermissionTags = (row: RoleInfo) => {
  if (row.is_super) {
    return ["自动拥有全部权限"];
  }
  if (row.permissions.length === 0) {
    return ["未授予任何权限"];
  }
  return row.permissions.map((key) => permissionNames.value[key] ?? key);
};

/**
 * 拍平后的权限点清单（用于勾选）。
 *
 * 为什么不按后端给的 group 渲染成分组树：当前 9 个权限点分布在 8 个分组里，其中 **7 个
 * 分组只有 1 项**，而且组名与项名几乎逐字重复——组「站点管理」下的项就叫「站点管理」，
 * 组「评测管理」下的项就叫「评测管理」。渲染成分组树等于给 9 个复选框插进 8 个加粗标题
 * 加 8 段间距，除了把对话框撑长之外没有任何组织价值。
 *
 * 分组信息仍然保留在后端返回的数据里（`group` 字段），等权限点数量上去、分组真正能承载
 * 「一类功能」的含义时，再按分组渲染即可——那时它会自己变得有用。
 */
const flatPermissions = computed(() => catalog.value.flatMap((group) => group.items));

const selectedCount = computed(() => editForm.value.permissions?.length ?? 0);
</script>

<template>
  <div class="permission-panel">
    <div class="panel-toolbar">
      <t-button theme="primary" @click="openCreate">新建角色</t-button>
      <span class="panel-hint">
        角色是权限点的集合，可授予用户（直接）或用户组（间接）。超管角色自动拥有全部权限点。
      </span>
    </div>

    <t-table
      row-key="id"
      :data="roles"
      :loading="loading"
      :scroll="{ x: 900 }"
      :columns="[
        { title: '标识', colKey: 'key', width: 160 },
        { title: '名称', colKey: 'name', width: 160 },
        { title: '说明', colKey: 'description', width: 220, ellipsis: true },
        { title: '权限点', colKey: 'permissions', width: 320 },
        { title: '引用', colKey: 'refs', width: 120 },
        { title: '操作', colKey: 'op', width: 140, fixed: 'right' },
      ]"
    >
      <template #key="{ row }">
        <t-space size="small">
          <span>{{ row.key }}</span>
          <t-tag v-if="row.is_super" theme="warning" size="small" variant="light">超管</t-tag>
          <t-tag v-else-if="row.is_builtin" theme="default" size="small" variant="light">内置</t-tag>
        </t-space>
      </template>

      <template #permissions="{ row }">
        <t-space size="small" break-line>
          <t-tag
            v-for="tag in rolePermissionTags(row)"
            :key="tag"
            size="small"
            variant="light"
            :theme="row.permissions.length === 0 && !row.is_super ? 'default' : 'primary'"
          >
            {{ tag }}
          </t-tag>
        </t-space>
      </template>

      <template #refs="{ row }">
        <t-link theme="primary" @click="openRefs(row)">
          {{ row.user_refs }} 用户 / {{ row.group_refs }} 组
        </t-link>
      </template>

      <template #op="{ row }">
        <t-space size="small">
          <t-link theme="primary" @click="openEdit(row)">编辑</t-link>
          <t-popconfirm
            content="删除后不可恢复。若该角色仍被引用，需要先解除引用。"
            @confirm="handleDelete(row)"
          >
            <t-link theme="danger">删除</t-link>
          </t-popconfirm>
        </t-space>
      </template>
    </t-table>

    <t-dialog
      v-model:visible="refsVisible"
      :header="`「${refs?.role_name || refs?.role_key || ''}」被谁引用`"
      :footer="false"
      width="640px"
    >
      <t-loading :loading="refsLoading">
        <template v-if="refs !== null">
          <t-alert
            v-if="refs.users.length === 0 && refs.groups.length === 0"
            theme="success"
            message="没有任何用户或用户组引用这个角色，可以安全删除。"
          />

          <div class="refs-block">
            <div class="refs-title">
              直接授予的用户
              <span class="refs-count">共 {{ refs.user_total }} 个</span>
            </div>
            <t-space v-if="refs.users.length > 0" size="small" break-line>
              <t-tag v-for="user in refs.users" :key="user.id" size="small" variant="light">
                {{ user.nickname || user.username }}（{{ user.username }}）
              </t-tag>
            </t-space>
            <div v-else class="permission-muted">无。这个角色没有被直接授予任何人。</div>
            <div v-if="refs.user_total > refs.users.length" class="permission-muted">
              仅列出前 {{ refs.users.length }} 个；解除引用时请以「用户授权」页的查询为准。
            </div>
          </div>

          <div class="refs-block">
            <div class="refs-title">
              绑定此角色的用户组
              <span class="refs-count">共 {{ refs.groups.length }} 个</span>
            </div>
            <t-space v-if="refs.groups.length > 0" size="small" break-line>
              <t-tag
                v-for="group in refs.groups"
                :key="group.id"
                size="small"
                theme="primary"
                variant="light"
              >
                {{ group.name || group.key }}（{{ group.member_count }} 名成员）
              </t-tag>
            </t-space>
            <div v-else class="permission-muted">无。没有用户组绑定这个角色。</div>
          </div>

          <div class="permission-muted refs-note">
            两类的处置方式不同：撤掉用户的**直接授权**只影响他本人；解绑用户组会同时影响
            组内全部成员。删除角色前需要两边都解除，否则会留下悬空的授权记录。
          </div>
        </template>
        <t-empty v-else description="加载中" />
      </t-loading>
    </t-dialog>

    <t-dialog
      v-model:visible="editVisible"
      :header="editTitle"
      :confirm-btn="{ loading: saving }"
      width="640px"
      @confirm="handleSave"
    >
      <t-form label-align="top">
        <t-form-item label="标识（key）">
          <t-input
            v-model="editForm.key"
            :disabled="editForm.id > 0 && editingBuiltin"
            placeholder="如 r-assistant，创建后不建议再改"
          />
          <template #help>
            <span v-if="editForm.id > 0 && editingBuiltin">内置角色的标识不可修改。</span>
            <span v-else-if="editForm.id > 0">
              标识被授权记录引用，改名等同于数据迁移，因此编辑时不可修改。
            </span>
            <span v-else>仅允许字母、数字、下划线与连字符，创建后应保持稳定。</span>
          </template>
        </t-form-item>

        <t-form-item label="名称">
          <t-input v-model="editForm.name" placeholder="如 助教" />
        </t-form-item>

        <t-form-item label="说明">
          <t-textarea v-model="editForm.description" :autosize="{ minRows: 2 }" />
        </t-form-item>

        <t-form-item label="排序">
          <t-input-number v-model="editForm.sort" :min="0" />
        </t-form-item>

        <t-form-item label="权限点">
          <div v-if="editingSuper" class="super-hint">
            该角色是超级管理员，自动拥有全部权限点（含将来新增的），无需逐个勾选。
          </div>
          <div v-else class="permission-block">
            <div class="permission-block-head">
              <span class="panel-hint">
                勾选即代表该角色拥有；未勾选的一律不具备。已选
                <strong>{{ selectedCount }}</strong> / {{ flatPermissions.length }}
              </span>
            </div>
            <t-checkbox-group v-model="editForm.permissions" class="permission-grid">
              <t-checkbox
                v-for="item in flatPermissions"
                :key="item.key"
                :value="item.key"
                class="permission-item"
              >
                <span class="permission-item-name">{{ item.name }}</span>
                <span class="permission-item-desc">{{ item.description }}</span>
              </t-checkbox>
            </t-checkbox-group>
          </div>
        </t-form-item>
      </t-form>
    </t-dialog>
  </div>
</template>

<style scoped>
/* 工具栏与提示文字等共用规则在 panels.css（嵌套在 .permission-page 下），
   这里只放本面板特有的部分 */

.permission-block {
  width: 100%;
}

.permission-block-head {
  margin-bottom: 6px;
}

/* 两列平铺：9 个权限点一屏放得下，不必滚动 */
.permission-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 2px 12px;
  width: 100%;
  max-height: 340px;
  overflow-y: auto;
}

.permission-item {
  align-items: flex-start;
  padding: 6px 8px;
  border-radius: 4px;
}

.permission-item:hover {
  background: var(--td-bg-color-container-hover);
}

.permission-item-name {
  display: block;
  line-height: 1.5;
}

.permission-item-desc {
  display: block;
  color: var(--td-text-color-placeholder);
  font-size: 12px;
  line-height: 1.4;
  white-space: normal;
}

.super-hint {
  color: var(--td-text-color-secondary);
}

.refs-block {
  margin-bottom: 16px;
}

.refs-title {
  font-weight: 600;
  margin-bottom: 6px;
}

.refs-count {
  font-weight: 400;
  color: var(--td-text-color-secondary);
  font-size: 13px;
  margin-left: 6px;
}

.refs-note {
  line-height: 1.7;
  padding-top: 8px;
  border-top: 1px solid var(--td-component-stroke);
}
</style>
